const MONTHS = { enero: 'January', febrero: 'February', marzo: 'March', abril: 'April', mayo: 'May', junio: 'June', julio: 'July', agosto: 'August', septiembre: 'September', octubre: 'October', noviembre: 'November', diciembre: 'December' };
const EFFORT = { bajo: 'low', medio: 'medium', alto: 'high', 'muy alto': 'very high' };
const QKIND = { 'Opción múltiple': 'Multiple choice', 'Verdadero o falso': 'True or false', 'Respuesta corta': 'Short answer', 'Cálculo': 'Computation', 'Demostración': 'Proof',
  'Problema': 'Problem', 'Código': 'Code', 'Problema de programación': 'Programming problem', 'Diagrama': 'Diagram', 'Desarrollo': 'Essay', 'Oral': 'Oral' };

export const PATTERNS = [
  [/\b(lunes|martes|miércoles|jueves|viernes|sábado|domingo), (\d{1,2}) de (enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\b/g, (m, d, n, mo) => `${DAYS[d]}, ${MONTHS[mo]} ${n}`],
  [/^Tu próximo examen · /, 'Your next exam · '],
  [/^(Buenas noches|Buenos días|Buenas tardes)/, (m) => ({ 'Buenas noches': 'Good evening', 'Buenos días': 'Good morning', 'Buenas tardes': 'Good afternoon' })[m]],
  [/(\d+)\.º semestre/g, 'semester $1'], [/^Estoy en (\d+)\.º$/, 'I’m in semester $1'], [/^(\d+)\.º$/, '$1'],
  [/^En (\d+) días$/, 'In $1 days'], [/^En (\d+) semanas?$/, 'In $1 weeks'],
  [/^\+ Terminar (.+)$/, '+ Finish $1'], [/^Terminar la guía «(.+)» de (.+)$/, 'Finish the guide “$1” for $2'],
  [/(\d+) guías? · (\d+) aportes? · (\d+) conceptos en el mapa/, '$1 guides · $2 contributions · $3 concepts in the map'],
  [/^(.+) \((\d+) aportes?\)$/, '$1 ($2 contributions)'],
  [/(\d+) (?:estudiante contó|estudiantes contaron) lo que sabe/g, '$1 shared what they know'],
  [/(\d+) preguntas? de sus exámenes en el mapa/g, '$1 questions from their exams on the map'],
  [/Nadie contó nada todavía/, 'Nobody has shared anything yet'],
  [/^Banco de preguntas \((\d+)\)$/, 'Question bank ($1)'], [/^Banco de preguntas: /, 'Question bank: '],
  [/^(\d+) preguntas? de (\d+) evaluaci(?:ón|ones), en paráfrasis anónima\. Practica con ellas; no son para copiar\.$/, '$1 questions from $2 evaluations, anonymously paraphrased. Practice with them; they are not for copying.'],
  [/^(\d+) preguntas? · /, '$1 questions · '],
  [/^(Opción múltiple|Verdadero o falso|Respuesta corta|Cálculo|Demostración|Problema de programación|Problema|Código|Diagrama|Desarrollo|Oral) · /, (m, k) => `${QKIND[k]} · `],
  [/dificultad (\d) de 5/g, 'difficulty $1 of 5'], [/(\d+) puntos/g, '$1 points'],
  [/^Lo compartió (.+)$/, 'Shared by $1'], [/^· Hecha con (.+)$/, '· Made with $1'], [/^Hecha con (.+)$/, 'Made with $1'],
  [/^, esfuerzo (bajo|medio|alto|muy alto)$/, (m, e) => `, ${EFFORT[e]} effort`],
  [/^Usará (.+?) · (.+?) · (bajo|medio|alto|muy alto)\.(.*)$/, (m, p, mod, e, rest) => `It will use ${p} · ${mod} · ${EFFORT[e]}.${rest.replace(' Solo tú puedes editar esta guía.', ' Only you can edit this guide.').replace(' Suelta uno o varios archivos, o una carpeta entera: cada archivo va a tu IA con las instrucciones de Studium y vuelve aquí para que lo revises.', ' Drop one or more files, or a whole folder: each file goes to your AI with Studium’s instructions and comes back here for you to review.').replace(' Una guía larga puede tardar varios minutos; no cierres la página.', ' A long guide can take several minutes; don’t close the page.')}`],
  [/^Conectada: tu cuenta tiene (\d+) modelos?\. Usará (.+)\.$/, (m, n, l) => `Connected: your account has ${n} models. It will use ${l.replace(/ · (bajo|medio|alto|muy alto)$/, (x, e) => ` · ${EFFORT[e]}`)}.`],
  [/^¿Dónde consigo una clave de (.+)\?$/, 'Where do I get a $1 key?'],
  [/^Tu IA está escribiendo(?: la guía)?… ([\d.,]+) caracteres$/, 'Your AI is writing… $1 characters'],
  [/^Saltado: pesa más de 25 MB$/, 'Skipped: larger than 25 MB'], [/^Saltado: tu IA no lee ese formato desde Studium: expórtalo como PDF$/, 'Skipped: your AI can’t read that format from Studium: export it as PDF'],
  [/^Guía creada con (.+)$/, 'Guide created with $1'],
  [/^Studium tiene (\d+) conceptos, (\d+) preguntas y (\d+) ejemplos de (.+?)(?:; (\d+) de esos aportes son de (.+))?\.$/, (m, c, q, e, course, n, prof) => `Studium has ${c} concepts, ${q} questions and ${e} examples for ${course}${n ? `; ${n} of those contributions are from ${prof}` : ''}.`],
  [/^Explica (\d+) conceptos \((\d+) nuevos en el mapa\)\. (.+)\.$/, 'Explains $1 concepts ($2 new in the map). $3.'],
  [/^(\d+) conceptos \((\d+) nuevos en el mapa\), (\d+) preguntas, (\d+) ejemplos\.$/, '$1 concepts ($2 new in the map), $3 questions, $4 examples.'],
  [/^Aporte: (.+)$/, (m, k) => `Contribution: ${EN[k] ?? k}`],
  [/^Identificado (por su contenido|por su nombre|con tu IA \((.+)\)): revisa los datos, y pega el enlace donde lo compartiste\.$/, (m, how, who) => `Identified ${who ? `with your AI (${who})` : how === 'por su contenido' ? 'from its content' : 'from its name'}: check the details, and paste the link where you shared it.`],
  [/^Tu IA no pudo: (.+) Uso lo que Studium encontró\.$/, (m, why) => `Your AI couldn’t: ${EN[why] ?? why} Using what Studium found.`],
  [/^Lo lee tu navegador y (.+); el archivo no se sube a Studium\.$/, 'Your browser and $1 read it; the file is not uploaded to Studium.'],
  [/^Tu proveedor respondió: /, 'Your provider replied: '],
  [/^Pesa (.+) comprimido; el límite es (.+)\. Pide a tu IA una versión más corta\.$/, 'It weighs $1 compressed; the limit is $2. Ask your AI for a shorter version.'],
  [/^y (\d+) más$/, 'and $1 more'], [/^Ver (\d+) guías?$/, 'See $1 guides'],
  [/^(Inicio|Guías|Mapa|Biblioteca|Profes|Ajustes|Acerca|Fuentes|Aportar|Entrar) · Studium$/, (m, w) => `${EN[w]} · Studium`],
];
